function _normalizeGitLabCommitStatus(status) {
    var s = String(status.status || '').toLowerCase();
    var conclusion = (s === 'failed') ? 'failure'
        : (s === 'canceled') ? 'cancelled'
        : (s === 'success') ? 'success'
