    var s = state || {};
    var maxLaps = (typeof s.maxNoopLaps === 'number' && s.maxNoopLaps > 0)
        ? s.maxNoopLaps : DEFAULT_NOOP_LAP_MAX;
    var laps = consecutiveNoopLaps(s.markers, s.headSha);
