function restoreReworkArm(key, ticket, rule, repoInfo, effectiveConfig) {
    var prNumber = ticket && ticket.prNumber;
    if (!prNumber) {
        console.log('  ⏭️  ' + key + ' sweep: no PR anchor — nothing to restore');
        return false;
    }
    // gh-840 rework review (BLOCKING): live PR-carrier items carry
    // pr: null (queryPrs populates item.pr only under needsStatus), so the
    // head is probed fresh — without it the latch consult short-circuits,
    // the in-flight gate is skipped and the restore marker records
    // 'unknown'. The same probe feeds reworkArmGate below (no double read).
    var probedHead = null;
    var head = reworkLatchHeadOf(ticket);
    if (!head) {
        probedHead = prHeadAndLabels(repoInfo, prNumber);
        if (probedHead) head = probedHead.headSha;
    }
    if (consultReworkLatch(key, ticket, repoInfo, head).latched) return false;
    if (head && hasActiveLegRun(headWorkflowRunsSafe(repoInfo, head),
            reworkLatchModule.DEFAULT_LEG_WORKFLOW)) {
        console.log('  ⏭️  ' + key + ' sweep: a leg run is active on head ' +
            String(head).substring(0, 7) + ' — the leg owns the threads');
        return false;
    }
    var machineLogins = verdictMachineLogins(effectiveConfig);
    var armGate = reworkArmGate(repoInfo, ticket, machineLogins, probedHead);
    if (!armGate.arm) {
        console.log('  ⏭️  ' + key + ' sweep: arm withheld — ' + armGate.reason +
            ' on head ' + armGate.headShort + ' (gh-807 verdict semantics preserved)');
        return false;
    }
    var comments = prCommentList(repoInfo, prNumber);
    var allow = { authorLogins: machineLogins };
    var consumed = reworkConsumptionModule.parseConsumeMarkers(comments, allow);
    var restored = reworkConsumptionModule.parseRestoreMarkers(comments, allow);
    var newestConsume = consumed.length ? consumed[consumed.length - 1] : null;
    var machineThreads = unresolvedMachineThreadCount(repoInfo, prNumber, machineLogins);
    if (machineThreads === -1) {
        console.log('  ⏭️  ' + key + ' sweep: machine-thread census unavailable — fail closed, retry next tick');
        return false;
    }
    var staleMin = (typeof rule.staleMinutes === 'number' && rule.staleMinutes > 0)
        ? rule.staleMinutes : Math.round(reworkConsumptionModule.DEFAULT_RESTORE_STALE_MS / 60000);
    // No head-position gate (gh-840 rework review, IMPORTANT): a head move
    // with the same open machine threads is a silentUpdateBranch refresh,
    // not a close — the close proof is thread ownership (the census above).
    var decision = reworkConsumptionModule.shouldRestoreArm({
        unresolvedMachineThreads: machineThreads,
        hasReworkLabel: false, // the rule query (notLabels) already guarantees this
        reworkInFlight: false, // latch + active-run gates above
        consumedAtMs: newestConsume ? newestConsume.atMs : null,
        restoredAtMs: restored.length ? restored[restored.length - 1].atMs : null,
        nowMs: Date.now(),
        staleMs: staleMin * 60 * 1000
    });
    if (!decision.restore) {
        console.log('  ⏭️  ' + key + ' sweep: no restore (' + decision.reason + ')');
        return false;
    }
    githubTracker(repoInfo.owner, repoInfo.repo).addLabel(prNumber, 'agent:rework');
    var markerBody = reworkConsumptionModule.buildRestoreMarkerComment(
        head || (newestConsume && newestConsume.head) || 'unknown', decision.reason);
    if (markerBody) {
        try {
            githubTracker(repoInfo.owner, repoInfo.repo).postComment(prNumber, markerBody);
        } catch (eMarker) {
            console.warn('  ⚠️ gh-840: restore marker comment failed (non-fatal): ' + (eMarker.message || eMarker));
        }
    }
    armReworkLatch(ticket, head);
    console.log('  🔄 ' + key + ' agent:rework RESTORED (gh-840: previous consumption left ' +
        machineThreads + ' machine thread(s) unresolved, quiet > ' +
        staleMin + 'm) — rework-on-label re-dispatches the leg');
    return true;
}

// AC2 — label reconciliation for one contradictory head: removes the loser
// label (winner APPROVE → agent:rework; winner REQUEST_CHANGES/BLOCK →
// pr_approved) from BOTH carriers (the PR and its linked issue) and posts
// ONE comment citing both verdict sources. Ruleset approvals / human review
// state are untouched — only the machine-owned label CARRIERS (pr_approved
// / agent:rework) reconcile. Returns true when a removal happened (item
// processed), false when the state is already consistent (nothing to do).
// gh-807 review fix (BLOCKING thread): before stripping agent:rework the
// action probes the head's CI verdict (headHasRealFailure, gh-755 —
// fail-open red): an APPROVE record does not invalidate CI-driven arms —
// red-CI rework on a sticky-approved PR (fail_validation), the sticky
// dead-letter issue arm, and conflict-rework on a DIRTY head all
// (the CI path owns the leg) — and so does the winning APPROVE record's
// OWN blocking census (rework round 2): blocking > 0 is exactly the
// evidence AC3's blocking-threads exception arms on (rework-unresolved-
// threads), so that arm is evidence-driven even on a green head. The
// census rides the decision function (reviewVerdicts.reconcileDecision);
// the probe runs only when a rework arm is actually present, so the
// conflict-shaped queries keep the cost near zero.
// machineLogins (gh-828 review round 2): the gh-728 machine-author
// allowlist the verdict records are parsed with — a forged marker must not
// strip labels or post reconciliation comments.
function reconcileReviewVerdicts(repoInfo, ticket, machineLogins) {
    var probe = prHeadAndLabels(repoInfo, ticket.prNumber);
    if (!probe) return false;
    var records = readVerdictRecords(repoInfo, ticket.prNumber, machineLogins);
    var issueLabels = linkedIssueLabels(repoInfo, ticket.issueNumber);
    var prHasRework = probe.labels.indexOf(reviewVerdictsModule.LABEL_REWORK) !== -1;
    var issueHasRework = !!(issueLabels &&
        issueLabels.indexOf(reviewVerdictsModule.LABEL_REWORK) !== -1);
    var checksRed = false;
    if (records.length && (prHasRework || issueHasRework)) {
        checksRed = headHasRealFailure(repoInfo, probe.headSha);
    }
    var decision = reviewVerdictsModule.reconcileDecision(records, probe.headSha, {
        prHasApproved: probe.labels.indexOf(reviewVerdictsModule.LABEL_APPROVED) !== -1,
        prHasRework: prHasRework,
        issueHasRework: issueHasRework,
        checksRed: checksRed
    });
    if (!decision) return false;
    var removed = false;
    if (decision.removeFromPr) {
        try {
            githubTracker(repoInfo.owner, repoInfo.repo).removeLabel(ticket.prNumber, decision.loserLabel);
            removed = true;
            console.log('  ⚖️  removed ' + decision.loserLabel + ' from PR #' + ticket.prNumber +
                ' (head ' + String(probe.headSha).substring(0, 7) + ')');
        } catch (ePr) {
            console.warn('  ⚠️ failed to remove ' + decision.loserLabel + ' from PR #' +
                ticket.prNumber + ': ' + (ePr.message || ePr));
        }
    }
    if (decision.removeFromIssue) {
        try {
            githubTracker(repoInfo.owner, repoInfo.repo).removeLabel(ticket.issueNumber, decision.loserLabel);
            removed = true;
            console.log('  ⚖️  removed ' + decision.loserLabel + ' from linked issue #' + ticket.issueNumber);
        } catch (eIss) {
            console.warn('  ⚠️ failed to remove ' + decision.loserLabel + ' from issue #' +
                ticket.issueNumber + ': ' + (eIss.message || eIss));
        }
    }
    if (removed) {
        try {
            githubTracker(repoInfo.owner, repoInfo.repo).postComment(ticket.prNumber, decision.comment);
        } catch (eC) {
            console.warn('  ⚠️ reconciliation comment failed (labels already reconciled): ' + (eC.message || eC));
        }
        console.log('  ✅ ' + ticket.key + ' verdict reconciled — newest wins: ' +
            decision.effective.record.verdict + (decision.effective.conflict ? ' (conflict logged)' : ''));
    }
    return removed;
}

