    if (!status) return null;
    var s = String(status).toLowerCase();
    if (s === 'failure' || s === 'failed') return 'failed';
    if (s === 'success' || s === 'succeeded') return 'success';
    if (s === 'in_progress') return 'running';
    if (s === 'queued' || s === 'pending') return 'pending';
