function postLapMarker(scm, prNumber, headSha, pushed, resolved) {
    var body = reworkLoopGuard.buildLapMarker(headSha, pushed, resolved, reworkRunUrl());
    if (!body) return;
    try {
        scm.addComment(prNumber, body);
