    function lapComment(head, n, max) {
        return { user: { login: 'ai-teammate' },
                 body: guard.noopLapMarkerPrefix(head) + ' lap ' + n + '/' + max +
                     ' resolved 0/0 unaddressed threads on the unchanged head (gh-957)' };
    }

